// Cache-Aside pattern (most common)
function getUser(id) {
  let user = cache.get(`user:${id}`);
  if (!user) {
    user = db.query('SELECT * FROM users WHERE id = ?', [id]);
    cache.set(`user:${id}`, user, 'EX', 3600);
  }
  return user;
}

