Event-Driven Architecture:
// Kafka producer with outbox pattern
import { Kafka } from 'kafkajs';

const kafka = new Kafka({ clientId: 'order-svc', brokers: ['kafka:9092'] });
const producer = kafka.producer();

async function createOrder(orderData) {
  const trx = await db.beginTransaction();
  try {
    // 1. Write to DB (atomic operation)
    const order = await trx.orders.create(orderData);

    // 2. Write event to outbox table (same DB transaction)
    await trx.outbox.create({
      aggregateType: 'order',
      aggregateId: order.id,
      eventType: 'OrderCreated',
      payload: JSON.stringify(order)
    });

    await trx.commit();

    // 3. Publish events from outbox (separate process)
    // Outbox publisher runs as a background job
    await publishOutboxEvents();
  } catch (err) {
    await trx.rollback();
    throw err;
  }
}

async function publishOutboxEvents() {
  await producer.connect();
  const events = await db.outbox.findUnpublished();
  for (const event of events) {
    await producer.send({
      topic: 'order-events',
      messages: [{ key: String(event.aggregateId), value: event.payload }]
    });
    await db.outbox.markPublished(event.id);
  }
}

