// k6 load test script
import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate, Trend } from 'k6/metrics';

const errorRate = new Rate('errors');
const orderLatency = new Trend('order_latency');

export const options = {
  stages: [
    { duration: '2m', target: 100 },  // Ramp up
    { duration: '5m', target: 100 },  // Stay
    { duration: '2m', target: 200 },  // Spike
    { duration: '3m', target: 0 },    // Ramp down
  ],
  thresholds: {
    http_req_duration: ['p(95)<500', 'p(99)<1000'],
    errors: ['rate<0.01'],
  }
};

export default function () {
  const headers = { 'Authorization': `Bearer ${__ENV.API_TOKEN}` };

  // GET orders list
  const listRes = http.get('http://api.example.com/api/orders?limit=20', { headers });
  check(listRes, { 'status 200': (r) => r.status === 200 });

  // GET single order
  const orderRes = http.get('http://api.example.com/api/orders/order-123', { headers });
  check(orderRes, { 'order status 200': (r) => r.status === 200 });
  orderLatency.add(orderRes.timings.duration);

  // POST create order
  const payload = JSON.stringify({
    items: [{ productId: 'prod-1', quantity: 1 }],
    shipping: { address: '123 Test St', zip: '12345' }
  });
  const createRes = http.post('http://api.example.com/api/orders', payload, {
    headers: { 'Content-Type': 'application/json', ...headers }
  });
  check(createRes, { 'created 201': (r) => r.status === 201 });
  errorRate.add(createRes.status >= 400);

  sleep(1);
}

